mermaid:
flowchart TD
    Req["GET /api/threads/x/artifacts/path"]
    Req --> Skill{".skill/ in path?"}
    Skill -->|yes| ResolveSkill["resolve_thread_virtual_path skill_file_path"]
    ResolveSkill --> ExistSkill{"exists and is_file?"}
    ExistSkill -->|no| Err404a["HTTPException 404/400"]
    ExistSkill -->|yes| Extract["_extract_file_from_skill_archive zip internal"]
    Extract --> MemberCap{"_read_skill_archive_member over 16MB?"}
    MemberCap -->|yes| Err413["HTTPException 413"]
    MemberCap -->|no| MimeSkill["mimetypes.guess_type internal_path"]
    MimeSkill --> SkillActive{"mime in ACTIVE_CONTENT_MIME_TYPES or download?"}
    SkillActive -->|yes| AttSkill["Response attachment + Cache-Control max-age=300"]
    SkillActive -->|no| SkillText{"mime starts text/?"}
    SkillText -->|yes| PlainSkill["PlainTextResponse utf-8"]
    SkillText -->|no| Decode{"decode utf-8 ok?"}
    Decode -->|yes| PlainDef["PlainTextResponse text/plain"]
    Decode -->|no| BinSkill["Response octet-stream"]
    Skill -->|no| ResolvePath["resolve_thread_virtual_path path"]
    ResolvePath --> ExistPath{"exists and is_file?"}
    ExistPath -->|no| Err404b["HTTPException 404/400"]
    ExistPath -->|yes| MimePath["mimetypes.guess_type actual_path"]
    MimePath --> WantDownload{"download query?"}
    WantDownload -->|yes| FileAtt["FileResponse attachment"]
    WantDownload -->|no| Active{"mime in ACTIVE_CONTENT_MIME_TYPES?"}
    Active -->|yes| FileActive["FileResponse attachment forced"]
    Active -->|no| TextMime{"mime starts text/?"}
    TextMime -->|yes| PlainText["PlainTextResponse read_text"]
    TextMime -->|no| TextProbe["is_text_file_by_content null-byte scan"]
    TextProbe -->|yes| PlainProbe["PlainTextResponse read_text"]
    TextProbe -->|no| InlineBin["Response inline Content-Disposition"]

flowchart TD
  Msg["thread message"] --> Hidden{isHiddenFromUIMessage}
  Hidden -- yes --> Skip["skip control msg"]
  Hidden -- no --> Type{"message.type"}
  Type -- human --> GHuman["human group"]
  Type -- tool --> Clar{isClarificationToolMessage}
  Type -- ai --> PF{hasPresentFiles}
  Clar -- yes --> GClar["assistant clarification"]
  Clar -- no --> Open["append lastOpenGroup"]
  PF -- yes --> GPF["assistant present-files"]
  PF -- no --> SA{hasSubagent}
  SA -- yes --> GSA["assistant subagent"]
  SA -- no --> RT{"hasReasoning or hasToolCalls"}
  RT -- yes --> GProc["assistant processing merge"]

flowchart TD
  Start["resolve_config_path called"] --> Arg{"config_path arg given"}
  Arg -- yes --> ArgPath["use provided path"]
  ArgPath --> Exists1{"file exists"}
  Exists1 -- no --> Err1["raise FileNotFoundError"]
  Exists1 -- yes --> Done["return resolved Path"]
  Arg -- no --> Env{"DEER_FLOW_CONFIG_PATH set"}
  Env -- yes --> EnvPath["use env var path"]
  EnvPath --> Exists2{"file exists"}
  Exists2 -- no --> Err2["raise FileNotFoundError"]
  Exists2 -- yes --> Done
  Env -- no --> Proj["existing_project_file config.yaml"]
  Proj --> ProjFound{"found in project root"}
  ProjFound -- yes --> Done
  ProjFound -- no --> Legacy["_legacy_config_candidates"]
  Legacy --> LegacyFound{"backend or repo config.yaml exists"}
  LegacyFound -- yes --> Done
  LegacyFound -- no --> Err3["raise FileNotFoundError"]
